/* ======================= HELPERS ======================= */
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
const NS='http://www.w3.org/2000/svg';
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function icon(k){const o=ICONS[k];return `<svg viewBox="${o.vb}" aria-hidden="true" ${o.fill?`fill="${o.fill}"`:''}>${o.body}</svg>`}

/* ======================= SITE CONTENT -> PAGE ======================= */
(function(){
  const R=SITE.resume,url=R.pdfReady?R.pdf:R.drive;
  $$('[data-resume]').forEach(a=>{a.href=url;if(R.pdfReady){a.removeAttribute('target');a.removeAttribute('rel');a.setAttribute('download','')}else{a.target='_blank';a.rel='noopener'}});
  $('#heroEyebrow').textContent=SITE.hero.eyebrow;$('#heroPara').textContent=SITE.hero.para;
  $('#ctaPrimary').firstChild.nodeValue=SITE.hero.primary+' ';
  $('#footTxt').textContent=SITE.footer;
  const pl=SITE.proof.filter(p=>has(p.n)&&has(p.l));
  $('#proofList').innerHTML=pl.map(p=>`<li><b>${esc(p.n)}</b><span>${esc(p.l)}</span></li>`).join('');
  if(!pl.length)$('#proof').hidden=true;
})();

/* reveal */
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.2,rootMargin:'0px 0px -6% 0px'});
$$('.rv,.circ').forEach(el=>io.observe(el));
$$('.hl').forEach(el=>io.observe(el));



/* ======================= HERO ======================= */
(function(){
  if(RM||matchMedia('(max-width:1000px)').matches)return;
  const hero=$('#home');const ps=$$('.patch');
  hero.addEventListener('pointermove',e=>{const r=hero.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;
    ps.forEach(p=>{const d=+p.dataset.d;p.style.transform=`translate(${x*d*1.6}px,${y*d*1.6}px) rotate(${d/9}deg)`})});
  ps.forEach(p=>p.style.transform=`rotate(${+p.dataset.d/9}deg)`);
})();

/* ======================= JOURNEY: VECTOR ISOMETRIC MINIATURE CITY ======================= */
const IW=1380,BGC='#F9F5EC';
const TL=34,OX=520,OY=190;
const P=(x,y,z=0)=>[OX+(x-y)*TL,OY+(x+y)*TL/2-z*TL];
const f1=n=>Math.round(n*10)/10;
const PS=a=>a.map(p=>f1(p[0])+','+f1(p[1])).join(' ');
const poly=(a,fill,ex='')=>`<polygon points="${PS(a)}" fill="${fill}" ${ex}/>`;
