const FM=(t,k,u,z)=>t==='L'?P(u,k,z):P(k,u,z);
const quad=(t,k,u0,u1,z0,z1,fill,ex='')=>poly([FM(t,k,u0,z0),FM(t,k,u1,z0),FM(t,k,u1,z1),FM(t,k,u0,z1)],fill,ex);
const topQ=(x0,y0,x1,y1,z,fill,ex='')=>poly([P(x0,y0,z),P(x1,y0,z),P(x1,y1,z),P(x0,y1,z)],fill,ex);
