const txtL=(x,y,z,t,sz,fill,ex='')=>{const[a,b]=P(x,y,z);return `<text transform="matrix(1 .5 0 1 ${f1(a)} ${f1(b)})" font-size="${sz}" font-family="Geist,Inter,Arial,sans-serif" font-weight="700" fill="${fill}" ${ex}>${t}</text>`};
const txtR=(x,y,z,t,sz,fill,ex='')=>{const[a,b]=P(x,y,z);return `<text transform="matrix(1 -.5 0 1 ${f1(a)} ${f1(b)})" font-size="${sz}" font-family="Geist,Inter,Arial,sans-serif" font-weight="700" fill="${fill}" ${ex}>${t}</text>`};
const ell=(x,y,z,r,fill,ex='')=>{const[a,b]=P(x,y,z);return `<ellipse cx="${f1(a)}" cy="${f1(b)}" rx="${f1(r*TL*1.414)}" ry="${f1(r*TL*.707)}" fill="${fill}" ${ex}/>`};
const shadowBox=(x,y,w,d,h,o=.16)=>poly([P(x+w,y+d,0),P(x+w,y,0),P(x+w+h*.7,y-h*.15,0),P(x+w+h*.7,y+d+h*.55,0),P(x+w,y+d+h*.55,0)],`rgba(14,18,28,${Math.min(.42,o*2)})`,'filter="url(#jBlur)"');
const WALL={
 brick:{t:'#D8D0C0',l:'#C4573E',r:'#9B4332'},sand:{t:'#EFE4C8',l:'#E5D0A0',r:'#C8AE7C'},
 glass:{t:'#D7E8E5',l:'#4FA9A1',r:'#3A8782'},yel:{t:'#F7EBC0',l:'#F6DB69',r:'#D8B83E'},
 white:{t:'#F4F1E8',l:'#FFFDF7',r:'#DDD7C7'},coral:{t:'#FAC9BE',l:'#F58774',r:'#D96B59'},
 slate:{t:'#C9CFCB',l:'#B5BDB8',r:'#98A19B'},wood:{t:'#C9A27A',l:'#B98A5E',r:'#9A7049'},
 roofR:{t:'#B8503A',l:'#D2664D',r:'#A5432F'},roofB:{t:'#4E5C66',l:'#667682',r:'#4A5963'},
 grn:{t:'#8FC47A',l:'#7CB267',r:'#5F9650'}};
function gable(x,y,w,d,z,r,c,rc){const ym=y+d/2;
  return poly([P(x,y+d,z),P(x+w,y+d,z),P(x+w,ym,z+r),P(x,ym,z+r)],rc.l,EDGE)+poly([P(x+w,y,z),P(x+w,y+d,z),P(x+w,ym,z+r)],c.r,EDGE)
   +poly([P(x,y+d,z),P(x+w,y+d,z),P(x+w,ym,z+r),P(x,ym,z+r)],'rgba(255,255,255,.10)')+poly([P(x,y+d,z),P(x+w,y+d,z),P(x+w,ym,z+r),P(x,ym,z+r)],'url(#gFT)')+poly([P(x+w,y,z),P(x+w,y+d,z),P(x+w,ym,z+r)],'url(#gFR)')+roofLines(x,y+d,x+w,y+d,x,ym,x+w,ym,z,r)}
function roofLines(ax,ay,bx,by,cx,cy,dx,dy,z,r){let s='';for(let k=1;k<7;k++){const t=k/7;s+=`<polyline points="${PS([P(ax+(cx-ax)*t,ay+(cy-ay)*t,z+r*t),P(bx+(dx-bx)*t,by+(dy-by)*t,z+r*t)])}" stroke="rgba(30,18,14,.2)" stroke-width=".9" fill="none"/>`}return s}
