/* ---------- route ---------- */
const ROUTE=[[-1,11],[4,11],[4,6],[9,6],[9,2],[14,2],[14,6],[18,6]];
const SEG=[];let TOT=0;for(let i=1;i<ROUTE.length;i++){const a=ROUTE[i-1],b=ROUTE[i],l=Math.hypot(b[0]-a[0],b[1]-a[1]);SEG.push({a,b,l,s0:TOT});TOT+=l}
const STOP_S=[2.7,12.9,21.5,31];
function gAt(s){s=clamp(s,0,TOT);let g=SEG[SEG.length-1];for(const k of SEG){if(s<=k.s0+k.l){g=k;break}}const t=(s-g.s0)/g.l;return{x:g.a[0]+(g.b[0]-g.a[0])*t,y:g.a[1]+(g.b[1]-g.a[1])*t,dx:g.b[0]-g.a[0],dy:g.b[1]-g.a[1]}}
function posAt(s){const g=gAt(s),p=P(g.x,g.y,0);return{x:p[0],y:p[1],dx:g.dx,dy:g.dy}}
function roadRects(hw,fill,ex=''){let s='';SEG.forEach((k,i)=>{let[x0,y0]=k.a,[x1,y1]=k.b;const hx=y0===y1,e=hw;
  if(hx){const xa=Math.min(x0,x1)-(i?e:0),xb=Math.max(x0,x1)+(i<SEG.length-1?e:0);s+=topQ(xa,y0-hw,xb,y0+hw,0,fill,ex)}
  else{const ya=Math.min(y0,y1)-e,yb=Math.max(y0,y1)+e;s+=topQ(x0-hw,ya,x0+hw,yb,0,fill,ex)}});return s}
function dashes(){let s='';SEG.forEach(k=>{const n=Math.floor(k.l*2.2),ux=(k.b[0]-k.a[0])/k.l,uy=(k.b[1]-k.a[1])/k.l;for(let i=0;i<n;i++){const t0=(i+.2)/n*k.l,t1=t0+.5*k.l/n;
  s+=poly([P(k.a[0]+ux*t0-uy*.04,k.a[1]+uy*t0+ux*.04,.01),P(k.a[0]+ux*t1-uy*.04,k.a[1]+uy*t1+ux*.04,.01),P(k.a[0]+ux*t1+uy*.04,k.a[1]+uy*t1-ux*.04,.01),P(k.a[0]+ux*t0+uy*.04,k.a[1]+uy*t0-ux*.04,.01)],'#FFFDF7')}});return s}
