const page=$('#page'),rsvg=$('#route'),rg=$('#rg'),rd=$('#rd'),rh=$('#rh');
let rLen=0,rTab=[],rTopY=0,rBotY=0;
function buildRoute(){
  if(getComputedStyle(rsvg).display==='none')return;
  const pr=page.getBoundingClientRect(),W=pr.width,H=pr.height;rsvg.setAttribute('viewBox',`0 0 ${W} ${H}`);rsvg.setAttribute('width',W);rsvg.setAttribute('height',H);
  const pts=$$('.wp').map(el=>{const r=el.getBoundingClientRect();return[(+el.dataset.wp)*W,r.top-pr.top+(r.height/2)]}).filter(p=>p[1]>=0);
  let d=`M${pts[0][0]} ${pts[0][1]}`;
  for(let i=1;i<pts.length;i++){const[a,b]=[pts[i-1],pts[i]];if(Math.abs(a[0]-b[0])<1){d+=`L${b[0]} ${b[1]}`}else{const k=Math.max(40,(b[1]-a[1])*.5);d+=`C${a[0]} ${a[1]+k} ${b[0]} ${b[1]-k} ${b[0]} ${b[1]}`}}
  rg.setAttribute('d',d);rd.setAttribute('d',d);rLen=rd.getTotalLength();rd.style.strokeDasharray=rLen;
  rTab=[];for(let l=0;l<=rLen;l+=10){const p=rd.getPointAtLength(l);rTab.push([l,p.y])}
  rTopY=pts[0][1];
}
function lenAtY(y){if(!rTab.length)return 0;let lo=0,hi=rTab.length-1;while(lo<hi){const m=(lo+hi)>>1;if(rTab[m][1]<y)lo=m+1;else hi=m}return rTab[lo][0]}
let rCur=0;
function paintRoute(){
  if(!rLen)return;const pr=page.getBoundingClientRect();const y=-pr.top+innerHeight*.62;
  const target=clamp(lenAtY(y),0,rLen);rCur=RM?target:rCur+(target-rCur)*.2;if(Math.abs(target-rCur)<.5)rCur=target;
  rd.style.strokeDashoffset=rLen-rCur;const q=rd.getPointAtLength(rCur);rh.setAttribute('cx',q.x);rh.setAttribute('cy',q.y);
  if(rCur!==target)requestAnimationFrame(paintRoute);
}


